{
  "name": "罗德与施瓦茨 SHM52 信号发生器",
  "name_en": "Rohde & Schwarz SHM52 Signal Generator",
  "manufacturer": "Rohde & Schwarz",
  "description": "一款射频信号发生器，频率范围约为 100 kHz 至 2 GHz。可用于实验与电子测试中的信号输出，支持设置频率、幅度以及输出开关。",
  "description_en": "An RF signal generator with an approximate frequency range of 100 kHz to 2 GHz. It is used for signal output in laboratory and electronic test setups, with support for frequency setting, amplitude setting, and output enable control.",
  "actions": [
    {
      "action_name": "auto-frequency",
      "description": "获取或设置输出频率。",
      "description_en": "Get or set the output frequency."
    },
    {
      "action_name": "auto-amplitude",
      "description": "获取或设置输出幅度。",
      "description_en": "Get or set the output amplitude."
    },
    {
      "action_name": "auto-output",
      "description": "获取或设置输出开关状态。",
      "description_en": "Get or set the output enable state."
    }
  ],
  "tag_hints": [
    "RF signal generation",
    "frequency control",
    "amplitude control",
    "signal source",
    "electronic test equipment",
    "2 GHz"
  ]
}

